SELECT COUNT(*) AS NumberOfConcerts
FROM concert
WHERE Stadium_ID = (SELECT Stadium_ID FROM stadium ORDER BY Capacity DESC LIMIT 1);

SELECT H.StuID, COUNT(H.PetID) AS PetCount
FROM Has_Pet H
GROUP BY H.StuID;

SELECT Has_Pet.StuID, COUNT(Has_Pet.PetID) AS PetCount
FROM Has_Pet
GROUP BY Has_Pet.StuID;

SELECT DISTINCT c.CountryId AS id, c.CountryName AS name
FROM countries c
JOIN car_makers m ON c.CountryId = m.Country;

SELECT T.Template_Type_Code, COUNT(*) AS Template_Count
FROM Templates T
GROUP BY T.Template_Type_Code;

SELECT DISTINCT T.Template_Details
FROM Templates T
JOIN Documents D ON T.Template_ID = D.Template_ID;

SELECT COUNT(DISTINCT winner_id) AS different_winners
FROM matches
WHERE winner_hand = 'left' AND tourney_name = 'WTA Championships';

SELECT COUNT(DISTINCT d.department_id) AS department_count
FROM Departments d
JOIN Degree_Programs dp ON d.department_id = dp.department_id;

SELECT DISTINCT a.line_1, a.line_2, a.line_3, a.city, a.zip_postcode, a.state_province_county, a.country
FROM Addresses a
JOIN Students s ON a.address_id = s.current_address_id OR a.address_id = s.permanent_address_id;

SELECT AVG(LifeExpectancy) AS AverageLifeExpectancy
FROM country
WHERE Continent = 'Africa' AND GovernmentForm LIKE '%Republic%';

SELECT DISTINCT c.Code FROM country c
JOIN countrylanguage cl ON c.Code = cl.CountryCode
WHERE cl.Language != 'English';

SELECT c.Code FROM country c
JOIN countrylanguage cl ON c.Code = cl.CountryCode
WHERE cl.Language != 'English' AND c.GovernmentForm != 'Republic';

SELECT COUNT(DISTINCT cl.CountryCode) AS CountryCount
FROM countrylanguage cl
WHERE cl.Language = 'Spanish' AND cl.IsOfficial = 'T';

SELECT COUNT(DISTINCT cl.CountryCode) AS TotalCountries
FROM countrylanguage cl
WHERE cl.Language = 'Spanish' AND cl.Percentage = (SELECT MAX(Percentage) FROM countrylanguage WHERE Language = 'Spanish');

SELECT c.Name AS Conductor_Name, o.Orchestra AS Orchestra_Name
FROM conductor c
JOIN orchestra o ON c.Conductor_ID = o.Conductor_ID;

SELECT c.Name AS Conductor_Name, o.Orchestra AS Orchestra_Name
FROM conductor c
JOIN orchestra o ON c.Conductor_ID = o.Conductor_ID;

SELECT F.student_id, COUNT(F.friend_id) AS number_of_friends
FROM Friend F
GROUP BY F.student_id;

SELECT DISTINCT f.student_id 
FROM Friend f 
JOIN Likes l ON f.student_id = l.student_id;

SELECT AVG(H.grade) AS average_grade
FROM Highschooler H
JOIN Friend F ON H.ID = F.student_id;

SELECT AVG(H.grade) AS average_grade
FROM Highschooler H
JOIN Friend F ON H.ID = F.student_id;

SELECT DISTINCT Owners.state
FROM Owners
JOIN Professionals ON Owners.state = Professionals.state;

SELECT DISTINCT Owners.state
FROM Owners
JOIN Professionals ON Owners.state = Professionals.state;

SELECT Treatments.cost_of_treatment, Treatment_Types.treatment_type_description 
FROM Treatments 
JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code;

SELECT COUNT(*) AS num_professionals_without_treatment
FROM Professionals
WHERE professional_id NOT IN (SELECT DISTINCT professional_id FROM Treatments);

SELECT COUNT(*) AS num_professionals_without_treatments
FROM Professionals
WHERE professional_id NOT IN (SELECT DISTINCT professional_id FROM Treatments);

SELECT Citizenship, MAX(Net_Worth_Millions) AS Max_Net_Worth
FROM singer
GROUP BY Citizenship;
